"""
Tamil Nadu dishes as standard recipes: raw ingredient grams for one batch + the cooked yield.
Nutrients per 100 g = sum(ingredients) / yield * 100. "@dish" uses another recipe (by cooked grams).

Batch sizes and yields are typical home amounts (hotel-style where the name says so). They are
estimates of portion and water content; ingredient values come from IFCT 2017.
"""

def D(id, name, tamil, emoji, cat, aliases, ing, yield_, units, defq=1.0, liquid=False, choices=None, hidden=False, source="recipe", note=""):
    return dict(id=id, name=name, tamil=tamil, emoji=emoji, cat=cat, aliases=aliases, ing=ing, yield_=yield_,
                units=units, defq=defq, liquid=liquid, choices=choices or [], hidden=hidden, source=source, note=note)

def G(id, label, options, multi=False, total=None, yieldf=1.0):
    """Choice group. multi=True: pick any; `total` grams are shared equally by the picked options."""
    return dict(id=id, label=label, options=options, multi=multi, total=total, yieldf=yieldf)

def O(id, label, ing=None, default=False):
    return dict(id=id, label=label, ing=ing or {}, default=default)

